// ── The verifier/solver gap — the essence of P vs NP ──────────────
//
// VERIFIER: polynomial time O(n) — checks a proposed solution
// SOLVER:   exponential time O(2^n) — must search for the solution
//
// This gap is what NP is all about.

// ── SAT verifier (polynomial) ──────────────────────────────────────
// Conjunctive Normal Form (CNF): AND of clauses, each clause = OR of literals.
// Literal: positive int = variable index (true), negative = negated (false).
function verifySAT(clauses, assignment) {
  // O(clauses * literals_per_clause) — polynomial
  return clauses.every(clause =>
    clause.some(lit => {
      const idx = Math.abs(lit);
      return lit > 0 ? assignment[idx] : !assignment[idx];
    })
  );
}

// Formula: (x1 ∨ x2) ∧ (¬x1 ∨ x3) ∧ (¬x2 ∨ ¬x3)
const clauses = [[1, 2], [-1, 3], [-2, -3]];

// Verification is O(n) — instant
console.log(verifySAT(clauses, { 1: true,  2: false, 3: true  })); // true  ✓
console.log(verifySAT(clauses, { 1: true,  2: true,  3: true  })); // false — (¬x2 ∨ ¬x3) fails
console.log(verifySAT(clauses, { 1: false, 2: false, 3: false })); // false — (¬x1 ∨ x3) fails

// ── SAT solver (exponential) ───────────────────────────────────────
// Try ALL 2^n assignments. No polynomial shortcut is known.
function solveSAT(clauses, numVars) {
  for (let mask = 0; mask < (1 << numVars); mask++) {
    const assignment = {};
    for (let i = 1; i <= numVars; i++) {
      assignment[i] = Boolean(mask & (1 << (i - 1)));
    }
    if (verifySAT(clauses, assignment)) return assignment;
  }
  return null; // unsatisfiable
}

const solution = solveSAT(clauses, 3);
console.log(solution);
// { 1: false, 2: true, 3: false } or another valid assignment
// For 3 variables: 2^3=8 attempts — trivial
// For 100 variables: 2^100 ≈ 10^30 attempts — impossible

// ── Subset Sum: verifier vs. brute-force solver ────────────────────

// Verifier: O(n) — check that the subset is valid and sums to target
function verifySubsetSum(set, subset, target) {
  // Each element of subset must appear in set (allowing repeats if set has them)
  const setCopy = [...set];
  for (const x of subset) {
    const idx = setCopy.indexOf(x);
    if (idx === -1) return false; // element not in set
    setCopy.splice(idx, 1);       // consume it
  }
  const sum = subset.reduce((a, b) => a + b, 0);
  return sum === target;
}

const set = [3, 1, 4, 1, 5, 9, 2, 6];
console.log(verifySubsetSum(set, [3, 4, 9], 16));   // true  (3+4+9=16)
console.log(verifySubsetSum(set, [3, 4, 9], 17));   // false
console.log(verifySubsetSum(set, [1, 5, 9], 15));   // true  (1+5+9=15)

// Solver: O(2^n) — enumerate all 2^n subsets
function solveSubsetSum(set, target) {
  const n = set.length;
  for (let mask = 1; mask < (1 << n); mask++) {
    let sum = 0;
    const subset = [];
    for (let i = 0; i < n; i++) {
      if (mask & (1 << i)) {
        sum += set[i];
        subset.push(set[i]);
      }
    }
    if (sum === target) return subset;
  }
  return null;
}

console.log(solveSubsetSum(set, 16)); // e.g. [3, 4, 9]
console.log(solveSubsetSum(set, 99)); // null — no subset sums to 99

// ── Note: there IS a pseudo-polynomial O(n*target) DP solution ─────
// This is why Subset Sum is 'only' weakly NP-complete — the input
// numbers' magnitudes matter, not just their count.
// Strongly NP-complete problems (like TSP) have no such DP shortcut.
function subsetSumDP(set, target) {
  const dp = new Array(target + 1).fill(false);
  dp[0] = true;
  for (const x of set) {
    // Traverse right-to-left to avoid using x twice
    for (let t = target; t >= x; t--) {
      if (dp[t - x]) dp[t] = true;
    }
  }
  return dp[target];
}
console.log(subsetSumDP(set, 16)); // true
console.log(subsetSumDP(set, 99)); // false

// ── Practical complexity in action: when to apply each strategy ───

// Scenario: you need to solve an NP-complete problem in production.
// Here is the decision framework.

function chooseStrategy(problemType, n, epsilon) {
  // Strategy 1: exact exponential — only for tiny inputs
  if (n <= 20) {
    return `Exact exponential O(2^n): feasible for n=${n} (${Math.pow(2,n).toLocaleString()} ops)`;
  }

  // Strategy 2: approximation — when provable bounds matter
  if (problemType === 'vertex-cover') {
    // Greedily pick uncovered edges, take both endpoints — O(E), 2-approx
    return '2-approximation: O(E) greedy, guaranteed within 2x optimal';
  }
  if (problemType === 'metric-tsp') {
    // Christofides: MST + min-weight perfect matching on odd-degree vertices
    return '1.5-approximation: Christofides, O(n^3) — guaranteed within 1.5x optimal';
  }

  // Strategy 3: heuristics — when approximation ratio unknown but practical perf is good
  if (problemType === 'sat' && n <= 10000) {
    return 'CDCL SAT solver: MiniSAT/Glucose — exponential worst-case, fast in practice';
  }

  // Strategy 4: parameterised — when a natural small parameter k exists
  // FPT algorithm for Vertex Cover: O(2^k * n)
  const k = 15; // small cover size
  if (problemType === 'vertex-cover' && k <= 30) {
    const fptOps = Math.pow(2, k) * n;
    return `FPT O(2^k * n) = O(2^${k} * ${n}) = ${fptOps.toLocaleString()} ops — feasible`;
  }

  return 'No known polynomial algorithm — NP-complete. Use approximation or heuristic.';
}

console.log(chooseStrategy('sat', 15, 0.1));
// Exact exponential: feasible for n=15

console.log(chooseStrategy('metric-tsp', 1000, 0.01));
// 1.5-approximation: Christofides, O(n^3) — guaranteed within 1.5x optimal

console.log(chooseStrategy('vertex-cover', 50000, 0.05));
// 2-approximation: O(E) greedy, guaranteed within 2x optimal

// ── 2-SAT in P via implication graph + SCC (O(V+E)) ──────────────
// 2-SAT: each clause has exactly 2 literals. Example: (x1 ∨ x2) ∧ (¬x1 ∨ x3)
// Convert each clause (a ∨ b) to two implications: (¬a → b) and (¬b → a)
// Build directed implication graph. Find SCCs via Kosaraju/Tarjan in O(V+E).
// x is satisfiable iff x and ¬x are NOT in the same SCC.
// 3-SAT: adding one literal destroys the polynomial structure — NP-complete.
console.log('2-SAT: P (implication graph + SCC). 3-SAT: NP-complete.');
console.log('One extra literal per clause is the difference between tractable and intractable.');
